selector_to_html = {"a[href=\"#build-automation\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Build Automation<a class=\"headerlink\" href=\"#build-automation\" title=\"Link to this heading\">#</a></h2><p>These workflows include development environment setup, linting,\ntesting, packaging, and deployment.  Document targets in the\n<a class=\"reference internal\" href=\"#detailed-contribution-guidelines\">detailed contribution guidelines</a>.</p>", "a[href=\"#the-main-branch\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">The Main Branch<a class=\"headerlink\" href=\"#the-main-branch\" title=\"Link to this heading\">#</a></h2><p>If a pre-existing Git repository uses a different name for the main\nbranch (e.g., <code class=\"docutils literal notranslate\"><span class=\"pre\">develop</span></code>, <code class=\"docutils literal notranslate\"><span class=\"pre\">master</span></code>), rename it if feasible.  For\nsimplicity\u2019s sake, this document assumes the main branch is called\n<code class=\"docutils literal notranslate\"><span class=\"pre\">main</span></code>.</p>", "a[href=\"#project-overview\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Project Overview<a class=\"headerlink\" href=\"#project-overview\" title=\"Link to this heading\">#</a></h2><p>That document starts with a level-1 heading containing the repository\nname, an single blank line, and the\n<a class=\"reference internal\" href=\"#description\">repository description</a>.  The rest of document includes\nquick reference material or abbreviated deployment guidance.  Refer\nthe <a class=\"reference internal\" href=\"../style/markdown.html\"><span class=\"doc std std-doc\">Markdown style guide</span></a> for further formatting\nguidance.</p>", "a[href=\"#intentionally-untracked-files\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Intentionally Untracked Files<a class=\"headerlink\" href=\"#intentionally-untracked-files\" title=\"Link to this heading\">#</a></h2><p>A <a class=\"reference external\" href=\"https://git-scm.com/docs/gitignore\"><code class=\"docutils literal notranslate\"><span class=\"pre\">.gitignore</span></code></a> file helps\nprevent\n<a class=\"reference external\" href=\"https://stackoverflow.com/a/13675249\">mistakenly committing junk data</a>.\nFor ideas on what to exclude, refer to\n<a class=\"reference external\" href=\"https://github.com/github/gitignore\">GitHub\u2019s collection of <code class=\"docutils literal notranslate\"><span class=\"pre\">.gitignore</span></code> templates</a>.</p>", "a[href=\"#common-repository-layout\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Common Repository Layout<a class=\"headerlink\" href=\"#common-repository-layout\" title=\"Link to this heading\">#</a></h1><p>All Git repositories share the same basic structure.  Some GitHub\norganizations publish\n<a class=\"reference external\" href=\"https://docs.github.com/en/repositories/creating-and-managing-repositories/creating-a-template-repository\">GitHub template repositories</a>\nto speed up the product creation or service definition process.  Refer\nto the selected template repository\u2019s documentation for further\ninstructions.</p>", "a[href=\"#hosting\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Hosting<a class=\"headerlink\" href=\"#hosting\" title=\"Link to this heading\">#</a></h2><p>For company projects, use the\n<a class=\"reference external\" href=\"https://github.com/ResearchDataCom\"><code class=\"docutils literal notranslate\"><span class=\"pre\">ResearchDataCom</span></code> organization on GitHub</a>.\nFor other customers, ask your program manager.</p>", "a[href=\"#description\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Description<a class=\"headerlink\" href=\"#description\" title=\"Link to this heading\">#</a></h2><p>Use this summary to describe the authoritative repository.</p>", "a[href=\"../style/markdown.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Markdown Style Guide<a class=\"headerlink\" href=\"#markdown-style-guide\" title=\"Link to this heading\">#</a></h1><p>Follow the\n<a class=\"reference external\" href=\"https://google.github.io/styleguide/docguide/style.html\">Google Markdown style guide</a>,\nbut use a more traditional 70-character line limit.  Use two spaces\nafter sentence-ending punctuation.</p>", "a[href=\"#detailed-contribution-guidelines\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Detailed Contribution Guidelines<a class=\"headerlink\" href=\"#detailed-contribution-guidelines\" title=\"Link to this heading\">#</a></h2><p>That document provides a more detailed specification of the project\u2019s\ndevelopment environment, its release engineering process, valid commit\ntypes/scopes, etc.  It also starts with the level-1 heading\n<code class=\"docutils literal notranslate\"><span class=\"pre\">Contribution</span> <span class=\"pre\">Guidelines</span></code>.</p>", "a[href=\"#naming\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Naming<a class=\"headerlink\" href=\"#naming\" title=\"Link to this heading\">#</a></h2><p>Use neutral language to name the project instead of abbreviations that\nmight not be understood by all audiences.  Limit an identifier\ncomposed of multiple terms to no more than three terms.  Separate\nmultiple terms using dashes, e.g., <code class=\"docutils literal notranslate\"><span class=\"pre\">example-service</span></code>, which is easier\nto read than if the terms were catenated.  Avoid characters that could\naffect cross-platform compatibility, including underscores, upper case\nletters, accents, special characters, or emojis.</p>", "a[href=\"#contribution-guidelines\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Contribution Guidelines<a class=\"headerlink\" href=\"#contribution-guidelines\" title=\"Link to this heading\">#</a></h2><p>That document starts with the level-1 heading <code class=\"docutils literal notranslate\"><span class=\"pre\">Contribution</span> <span class=\"pre\">Guidelines</span></code>, a single blank line, and a short summary of the project\u2019s\ndevelopment workflow.  It can also tailor this document\u2019s guidance,\nsuch as specifying <a class=\"reference internal\" href=\"#conventional#commit-types\"><span class=\"xref myst\">commit types</span></a> and\n<a class=\"reference internal\" href=\"#conventional#commit-scopes\"><span class=\"xref myst\">scopes</span></a>.  The link to the detailed\ncontribution guidelines should be a level-3 heading <code class=\"docutils literal notranslate\"><span class=\"pre\">Refer</span> <span class=\"pre\">to</span> <span class=\"pre\">the</span> <span class=\"pre\">project</span> <span class=\"pre\">documentation</span> <span class=\"pre\">for</span> <span class=\"pre\">more</span> <span class=\"pre\">information.</span></code></p>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
